// Milestone 9 Layer 1: Financial Trading Desk Topology & Data Structures
class TradingDeskTopology {
  constructor() {
    this.instruments = new Map();
    this.microFrontends = ['MarketDepthRemote', 'OrderExecutionRemote', 'RiskAnalyticsRemote'];
    this.initInstruments();
  }

  initInstruments() {
    const symbols = ['AAPL', 'NVDA', 'MSFT', 'AMZN', 'GOOGL'];
    symbols.forEach((sym, idx) => {
      this.instruments.set(sym, {
        symbol: sym,
        lastPrice: 150.00 + idx * 25.5,
        bid: 149.95 + idx * 25.5,
        ask: 150.05 + idx * 25.5,
        volume24h: 1250000 + idx * 100000,
        volatilityIndex: 0.18 + idx * 0.02
      });
    });
  }

  getInstrumentSummary(symbol) {
    const inst = this.instruments.get(symbol);
    if (!inst) return null;
    const spread = +(inst.ask - inst.bid).toFixed(2);
    return { symbol: inst.symbol, lastPrice: inst.lastPrice, spread, volume: inst.volume24h };
  }
}

