// Milestone 9 Layer 2: High-Frequency Market Feed Store with useSyncExternalStore
class HighFrequencyMarketStore {
  constructor() {
    this.quotes = {};
    this.listeners = new Set();
    this.tickCount = 0;
  }

  setInitialQuotes(initialData) {
    this.quotes = Object.assign({}, initialData);
  }

  getState() {
    return this.quotes;
  }

  // High-frequency ingest: updates internal state without heap churn
  ingestTick(symbol, newPrice) {
    this.tickCount++;
    const oldQuote = this.quotes[symbol] || { lastPrice: newPrice };
    this.quotes[symbol] = {
      symbol,
      lastPrice: newPrice,
      bid: +(newPrice - 0.05).toFixed(2),
      ask: +(newPrice + 0.05).toFixed(2),
      timestamp: 1700000000000 + this.tickCount
    };
    this.listeners.forEach(fn => fn());
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
}

// Simulated useSyncExternalStore Component Subscriber with Memoized Selector
class MarketWidgetSubscriber {
  constructor(name, store, symbol) {
    this.name = name;
    this.store = store;
    this.symbol = symbol;
    this.lastPrice = this.getPrice();
    this.reRenderCount = 0;

    this.unsubscribe = this.store.subscribe(() => {
      const nextPrice = this.getPrice();
      if (nextPrice !== this.lastPrice) {
        this.lastPrice = nextPrice;
        this.reRenderCount++;
      }
    });
  }

  getPrice() {
    const q = this.store.getState()[this.symbol];
    return q ? q.lastPrice : null;
  }
}

