// Milestone 9 Layer 3: Order Execution Statechart Engine
class OrderExecutionMachine {
  constructor(accountBalance = 100000) {
    this.state = 'IDLE';
    this.accountBalance = accountBalance;
    this.context = {
      orderId: null,
      symbol: null,
      quantity: 0,
      limitPrice: 0,
      rejectionReason: null,
      filledQuantity: 0
    };
  }

  transition(event) {
    switch (this.state) {
      case 'IDLE':
        if (event.type === 'PREPARE_ORDER') {
          // Guard 1: Buying power check
          const totalCapitalRequired = event.quantity * event.limitPrice;
          if (totalCapitalRequired > this.accountBalance) {
            this.state = 'REJECTED';
            this.context.rejectionReason = 'INSUFFICIENT_MARGIN: Required $' + totalCapitalRequired + ' > Balance $' + this.accountBalance;
            return;
          }
          // Guard 2: Quantity sanity check
          if (event.quantity <= 0 || event.quantity > 5000) {
            this.state = 'REJECTED';
            this.context.rejectionReason = 'INVALID_QUANTITY: Exceeds single-order threshold';
            return;
          }

          this.context.symbol = event.symbol;
          this.context.quantity = event.quantity;
          this.context.limitPrice = event.limitPrice;
          this.state = 'VALIDATING_RISK';
          this.executeRiskValidation();
        }
        break;

      case 'VALIDATING_RISK':
        if (event.type === 'RISK_PASSED') {
          this.state = 'SUBMITTING_EXCHANGE';
          this.submitToExchange();
        }
        break;

      case 'SUBMITTING_EXCHANGE':
        if (event.type === 'EXCHANGE_ACK') {
          this.context.orderId = event.orderId;
          this.state = 'ACKNOWLEDGED';
        }
        break;

      case 'ACKNOWLEDGED':
        if (event.type === 'FILL') {
          this.context.filledQuantity = event.fillQty;
          this.state = 'FILLED';
        }
        break;

      case 'FILLED':
      case 'REJECTED':
        // Terminal states
        break;
    }
  }

  executeRiskValidation() {
    this.transition({ type: 'RISK_PASSED' });
  }

  submitToExchange() {
    this.transition({ type: 'EXCHANGE_ACK', orderId: 'EXCH-ORD-99124' });
  }
}

