// Milestone 9 Layer 4: Federated Micro-Frontend Desk Orchestrator
class FederatedTradingDeskOrchestrator {
  constructor() {
    this.sharedScope = {};
    this.remotes = new Map();
    this.eventBus = new Set();
    this.mountedWidgets = {};
  }

  initSharedScope(sharedPackages) {
    this.sharedScope = Object.assign({}, sharedPackages);
  }

  registerRemote(name, manifest) {
    this.remotes.set(name, manifest);
  }

  mountRemoteWidget(remoteName, widgetName) {
    const remote = this.remotes.get(remoteName);
    if (!remote) throw new Error('Remote not found: ' + remoteName);
    const widgetFactory = remote.widgets[widgetName];
    if (!widgetFactory) throw new Error('Widget not found: ' + widgetName);

    const widget = widgetFactory(this.sharedScope);
    this.mountedWidgets[widgetName] = widget;
    return widget;
  }

  broadcast(event) {
    this.eventBus.forEach(listener => listener(event));
  }

  subscribe(listener) {
    this.eventBus.add(listener);
    return () => this.eventBus.delete(listener);
  }
}

